// Extract receipt data from email
const email = $input.first().json;
const subject = email.subject || '';
const body = email.text || email.snippet || '';
const from = email.from || '';

// Extract amount from subject/body
const amountPatterns = [
  /\$([0-9,]+\.\d{2})/,
  /Total:?\s*\$([0-9,]+\.\d{2})/i,
  /Amount:?\s*\$([0-9,]+\.\d{2})/i,
  /Charge:?\s*\$([0-9,]+\.\d{2})/i,
  /Payment:?\s*\$([0-9,]+\.\d{2})/i
];

let amount = null;
for (const pattern of amountPatterns) {
  const match = subject.match(pattern) || body.match(pattern);
  if (match) {
    amount = parseFloat(match[1].replace(',', ''));
    break;
  }
}

// Extract merchant from sender domain
const senderDomainMatch = from.match(/@([a-zA-Z0-9.-]+)/i);
let merchant = 'Unknown';
if (senderDomainMatch) {
  const domain = senderDomainMatch[1].toLowerCase();
  // Common service mappings
  const domainMap = {
    'framer.com': 'Framer',
    'openai.com': 'OpenAI',
    'anthropic.com': 'Anthropic',
    'stripe.com': 'Stripe',
    'notion.so': 'Notion',
    'vercel.com': 'Vercel',
    'github.com': 'GitHub',
    'amazon.com': 'AWS',
    'aws.amazon.com': 'AWS',
    'dropbox.com': 'Dropbox',
    'slack.com': 'Slack',
    'digitalocean.com': 'DigitalOcean',
    'heroku.com': 'Heroku',
    'netlify.com': 'Netlify',
    'twilio.com': 'Twilio',
    'sendgrid.com': 'SendGrid',
    'zoom.us': 'Zoom',
    'adobe.com': 'Adobe',
    'figma.com': 'Figma',
    'google.com': 'Google',
    'microsoft.com': 'Microsoft'
  };

  merchant = domainMap[domain] || domain.split('.')[0].charAt(0).toUpperCase() + domain.split('.')[0].slice(1);
}

// Extract date from email
const emailDate = new Date(email.date || email.internalDate).toISOString().split('T')[0];

// Get PDF attachment
let attachment = null;
if (email.attachments && email.attachments.length > 0) {
  // Prefer PDF with invoice/receipt in name
  attachment = email.attachments.find(a => 
    a.filename && a.filename.toLowerCase().includes('invoice')
  ) || email.attachments.find(a => 
    a.filename && a.filename.toLowerCase().includes('receipt')
  ) || email.attachments.find(a => 
    a.filename && a.filename.toLowerCase().endsWith('.pdf')
  ) || email.attachments[0];
}

return [{
  json: {
    emailId: email.id,
    subject,
    from,
    merchant,
    amount,
    date: emailDate,
    hasAttachment: !!attachment,
    attachmentName: attachment?.filename || '',
    attachmentData: attachment?.data || null,
    attachmentMimeType: attachment?.mimeType || ''
  }
}];

// Build Google Drive folder path and filename
const input = $input.first().json;
const date = new Date(input.date);
const year = date.getFullYear();
const month = String(date.getMonth() + 1).padStart(2, '0');

const folderPath = `Business/Receipts/${year}/${month}`;

// Generate filename
let filename;
if (input.amount) {
  filename = `${input.merchant}_${input.date}_$${input.amount.toFixed(2)}.pdf`;
} else {
  filename = `${input.merchant}_${input.date}_Receipt.pdf`;
}

// Clean filename (remove invalid characters)
filename = filename.replace(/[<>:"/\\|?*]/g, '_');

return [{
  json: {
    ...input,
    folderPath,
    filename,
    year,
    month
  }
}];

// Build Drive share URL
const fileId = $input.first().json.id;
const receiptUrl = `https://drive.google.com/file/d/${fileId}/view`;

// Get original data from earlier node
const extractData = $('Code - Build Drive Path').first().json;

return [{
  json: {
    ...extractData,
    driveFileId: fileId,
    receiptUrl
  }
}];

