// Match receipt to expense
const receiptData = $('Code - Get Share URL').first().json;
const expenses = $input.all();

if (!expenses || expenses.length === 0) {
  return [{
    json: {
      ...receiptData,
      matched: false,
      matchedExpense: null,
      matchScore: 0,
      reason: 'No pending expenses found in date range'
    }
  }];
}

// Calculate similarity score
const similarity = (str1, str2) => {
  if (!str1 || !str2) return 0;
  const s1 = str1.toLowerCase().trim();
  const s2 = str2.toLowerCase().trim();

  // Exact match
  if (s1 === s2) return 100;

  // Contains match
  if (s1.includes(s2) || s2.includes(s1)) return 80;

  // Word overlap
  const words1 = s1.split(/\s+/);
  const words2 = s2.split(/\s+/);
  const overlap = words1.filter(w => words2.some(w2 => w2.includes(w) || w.includes(w2))).length;
  const maxWords = Math.max(words1.length, words2.length);

  return Math.round((overlap / maxWords) * 60);
};

// Find best match
let bestMatch = null;
let bestScore = 0;

for (const item of expenses) {
  const expense = item.json;
  const expenseTitle = expense.properties?.Expense?.title?.[0]?.plain_text || '';
  const expenseAmount = expense.properties?.Amount?.number || 0;

  let score = 0;

  // Merchant name similarity (max 50 points)
  const merchantScore = similarity(receiptData.merchant, expenseTitle);
  score += merchantScore * 0.5;

  // Amount match (max 50 points)
  if (receiptData.amount && expenseAmount) {
    const amountDiff = Math.abs(receiptData.amount - expenseAmount);
    if (amountDiff < 0.01) {
      score += 50; // Exact match
    } else if (amountDiff <= 5) {
      score += 40; // Within $5
    } else if (amountDiff <= 10) {
      score += 30; // Within $10
    }
  }

  if (score > bestScore) {
    bestScore = score;
    bestMatch = expense;
  }
}

const matched = bestScore >= 50; // Threshold for auto-matching

return [{
  json: {
    ...receiptData,
    matched,
    matchedExpense: matched ? bestMatch : null,
    matchedExpenseId: matched ? bestMatch?.id : null,
    matchedExpenseUrl: matched ? bestMatch?.url : null,
    matchScore: Math.round(bestScore),
    reason: matched ? 'Found matching expense' : `Best score ${Math.round(bestScore)} below threshold 50`
  }
}];

